  function shrink(file, max) { return new Promise(function (ok, no) { if (/svg/.test(file.type)) { var r = new FileReader(); r.onload = function () { ok(r.result); }; r.onerror = no; r.readAsDataURL(file); return; } var u = URL.createObjectURL(file), im = new Image(); im.onload = function () { var sc = Math.min(1, max / Math.max(im.naturalWidth, im.naturalHeight)), c = document.createElement('canvas'); c.width = Math.round(im.naturalWidth * sc); c.height = Math.round(im.naturalHeight * sc); c.getContext('2d').drawImage(im, 0, 0, c.width, c.height); URL.revokeObjectURL(u); ok(c.toDataURL('image/png')); }; im.onerror = function () { no(Error('That image could not be read.')); }; im.src = u; }); }
