        + (own ? '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:8px"><input id="inv-' + t.id + '" type="email" placeholder="Email they sign in with" style="flex:1;min-width:200px"><select id="invr-' + t.id + '"><option>editor</option><option>viewer</option></select><button class="dbtn" type="button" data-t="invite" data-id="' + t.id + '">Invite</button></div><p class="sub">They see the invitation here after signing in to Forecut with that email.</p>' : '')
